 private static final int BG=0xff101b23,SURFACE=0xff192a33,INK=0xffece8dd,MUTED=0xff9bafaf,MINT=0xffa7dac6;
 private RuntimeClient client;private JSONObject state;private LinearLayout root,content,nav;private ScrollView scroll;private TextView connection,learnStatus;private EditText examples;private WebView world;private String tab="Runtime",pendingExport,exportMime;private final java.util.concurrent.ExecutorService fileIO=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private boolean active=false,polling=false;private AgentFieldView field;
