  LinearLayout header=row();header.setPadding(dp(22),dp(16),dp(16),dp(10));TextView brand=text("synthia",27,INK);brand.setTypeface(Typeface.create("sans-serif-medium",0));header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));header.addView(button("Settings",this::connectionDialog));root.addView(header);
  connection=text("Starting the on-device runtime…",12,MUTED);connection.setPadding(dp(22),0,dp(22),dp(14));connection.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);root.addView(connection);
  scroll=new ScrollView(this);scroll.setFillViewport(true);content=column();content.setPadding(dp(22),dp(8),dp(22),dp(24));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
